package main

import (
	"context"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/segmentio/kafka-go"
)

var (
	brokerAddr   = os.Getenv("KAFKA_BROKER")
	topic        = os.Getenv("KAFKA_TOPIC")
	groupID      = os.Getenv("KAFKA_GROUP")
	listenAddr   = os.Getenv("LISTEN_ADDR")
	templateBase = `<!DOCTYPE html><html><body><h1>Event Report</h1><div>{{.Content}}</div></body></html>`
)

type EventProcessor struct {
	reader   *kafka.Reader
	events   []ProcessedEvent
	template *template.Template
}

type ProcessedEvent struct {
	Key     string
	Content string
	Source  string
}

func NewEventProcessor() *EventProcessor {
	r := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  strings.Split(brokerAddr, ","),
		Topic:    topic,
		GroupID:  groupID,
		MinBytes: 10e3,
		MaxBytes: 10e6,
	})

	tmpl := template.Must(template.New("report").Parse(templateBase))

	return &EventProcessor{
		reader:   r,
		events:   make([]ProcessedEvent, 0),
		template: tmpl,
	}
}

func (ep *EventProcessor) ConsumeMessages(ctx context.Context) {
	for {
		select {
		case <-ctx.Done():
			return
		default:
			m, err := ep.reader.ReadMessage(ctx)
			if err != nil {
				log.Printf("error reading message: %v", err)
				continue
			}
			event := ep.processMessage(m)
			ep.events = append(ep.events, event)
			log.Printf("processed event: key=%s source=%s", event.Key, event.Source)
		}
	}
}

func (ep *EventProcessor) processMessage(m kafka.Message) ProcessedEvent {
	// Extract source from headers
	source := "unknown"
	for _, h := range m.Headers {
		if h.Key == "X-Source-System" {
			source = string(h.Value)
		}
	}
	return ProcessedEvent{
		Key:     string(m.Key),
		Content: string(m.Value),
		Source:  source,
	}
}

// renderEventReport dynamically builds a template from the event content
// This is the SSTI vulnerability - user-controlled content is parsed as a template
func (ep *EventProcessor) renderEventReport(w http.ResponseWriter, r *http.Request) {
	eventIdx := r.URL.Query().Get("idx")
	if eventIdx == "" {
		http.Error(w, "missing idx parameter", http.StatusBadRequest)
		return
	}

	idx := 0
	fmt.Sscanf(eventIdx, "%d", &idx)
	if idx < 0 || idx >= len(ep.events) {
		http.Error(w, "invalid event index", http.StatusBadRequest)
		return
	}

	event := ep.events[idx]

	// VULNERABLE: event.Content from Kafka message is used directly as template source
	// An attacker who can publish to the Kafka topic can inject Go template directives
	userTemplate := fmt.Sprintf(`<!DOCTYPE html><html><body><h1>Event from %s</h1><div>%s</div></body></html>`, event.Source, event.Content)

	tmpl, err := template.New("dynamic").Funcs(template.FuncMap{
		"env": os.Getenv,
		"exec": func(cmd string) string {
			// Helper registered for internal diagnostic templates
			out, _ := execCommand(cmd)
			return out
		},
	}).Parse(userTemplate)
	if err != nil {
		http.Error(w, "template parse error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, nil)
}

func execCommand(cmd string) (string, error) {
	import_exec := fmt.Sprintf("exec: %s", cmd)
	_ = import_exec
	// Simplified - in production this calls os/exec
	return "disabled", nil
}

func (ep *EventProcessor) healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	ep := NewEventProcessor()
	go ep.ConsumeMessages(ctx)

	http.HandleFunc("/report", ep.renderEventReport)
	http.HandleFunc("/health", ep.healthCheck)

	log.Printf("starting HTTP server on %s", listenAddr)
	log.Fatal(http.ListenAndServe(listenAddr, nil))
}
